window.__I18N_SITE=Object.assign(window.__I18N_SITE||{},{"Публичная оферта HarmonyAI Pro":{"en":"HarmonyAI Pro Public Offer","fr":"Offre publique HarmonyAI Pro","de":"Öffentliches Angebot HarmonyAI Pro","es":"Oferta pública de HarmonyAI Pro","it":"Offerta pubblica HarmonyAI Pro","zh":"HarmonyAI Pro 公开要约"},"ПУБЛИЧНАЯ ОФЕРТА о предоставлении доступа к сервису HarmonyAI Pro по подписке":{"en":"PUBLIC OFFER for subscription-based access to the HarmonyAI Pro service","fr":"OFFRE PUBLIQUE d’accès au service HarmonyAI Pro par abonnement","de":"ÖFFENTLICHES ANGEBOT über den abonnementbasierten Zugang zum Dienst HarmonyAI Pro","es":"OFERTA PÚBLICA de acceso al servicio HarmonyAI Pro por suscripción","it":"OFFERTA PUBBLICA di accesso al servizio HarmonyAI Pro in abbonamento","zh":"关于以订阅方式提供 HarmonyAI Pro 服务访问权限的公开要约"},"Дата вступления в силу: 5 сентября 2026 г.":{"en":"Effective date: 5 September 2026","fr":"Date d’entrée en vigueur : 5 septembre 2026","de":"Inkrafttreten: 5. September 2026","es":"Fecha de entrada en vigor: 5 de septiembre de 2026","it":"Data di entrata in vigore: 5 settembre 2026","zh":"生效日期：2026 年 9 月 5 日"},"1. Термины и определения":{"en":"1. Terms and definitions","fr":"1. Termes et définitions","de":"1. Begriffe und Definitionen","es":"1. Términos y definiciones","it":"1. Termini e definizioni","zh":"1. 术语与定义"},"Оферта":{"en":"Offer","fr":"Offre","de":"Angebot","es":"Oferta","it":"Offerta","zh":"要约"},"— настоящий документ, размещённый в сети Интернет по адресу harmonyai.ru/legal/ofera.html и являющийся публичным предложением заключить договор на условиях, в нём изложенных.":{"en":"— this document, published on the Internet at harmonyai.ru/legal/ofera.html, which is a public proposal to conclude a contract on the terms set out in it.","fr":"— le présent document, publié sur Internet à l’adresse harmonyai.ru/legal/ofera.html et constituant une proposition publique de conclure un contrat aux conditions qui y sont énoncées.","de":"— dieses im Internet unter harmonyai.ru/legal/ofera.html veröffentlichte Dokument, das ein öffentliches Angebot zum Abschluss eines Vertrags zu den darin genannten Bedingungen darstellt.","es":"— el presente documento, publicado en internet en harmonyai.ru/legal/ofera.html, que constituye una propuesta pública de celebrar un contrato en las condiciones que en él se establecen.","it":"— il presente documento, pubblicato su Internet all’indirizzo harmonyai.ru/legal/ofera.html, che costituisce una proposta pubblica di concludere un contratto alle condizioni in esso indicate.","zh":"——指发布于互联网 harmonyai.ru/legal/ofera.html 的本文件，系按其所载条件订立合同的公开提议。"},"Сервис":{"en":"Service","fr":"Service","de":"Dienst","es":"Servicio","it":"Servizio","zh":"服务"},"— веб-приложение HarmonyAI, доступное по адресам harmonyai.ru и harmonyai-zeta.vercel.app, включая его платные функции.":{"en":"— the HarmonyAI web application available at harmonyai.ru and harmonyai-zeta.vercel.app, including its paid features.","fr":"— l’application web HarmonyAI accessible aux adresses harmonyai.ru et harmonyai-zeta.vercel.app, y compris ses fonctions payantes.","de":"— die Webanwendung HarmonyAI unter den Adressen harmonyai.ru und harmonyai-zeta.vercel.app, einschließlich ihrer kostenpflichtigen Funktionen.","es":"— la aplicación web HarmonyAI disponible en harmonyai.ru y harmonyai-zeta.vercel.app, incluidas sus funciones de pago.","it":"— l’applicazione web HarmonyAI disponibile agli indirizzi harmonyai.ru e harmonyai-zeta.vercel.app, comprese le sue funzioni a pagamento.","zh":"——指可通过 harmonyai.ru 和 harmonyai-zeta.vercel.app 访问的 HarmonyAI 网页应用，包括其付费功能。"},"Пользователь":{"en":"User","fr":"Utilisateur","de":"Nutzer","es":"Usuario","it":"Utente","zh":"用户"},"— физическое лицо, акцептовавшее настоящую Оферту и оформившее подписку HarmonyAI Pro.":{"en":"— an individual who has accepted this Offer and taken out a HarmonyAI Pro subscription.","fr":"— une personne physique ayant accepté la présente Offre et souscrit à l’abonnement HarmonyAI Pro.","de":"— eine natürliche Person, die dieses Angebot angenommen und ein HarmonyAI-Pro-Abo abgeschlossen hat.","es":"— persona física que ha aceptado la presente Oferta y ha contratado la suscripción HarmonyAI Pro.","it":"— persona fisica che ha accettato la presente Offerta e ha attivato l’abbonamento HarmonyAI Pro.","zh":"——指接受本要约并开通 HarmonyAI Pro 订阅的自然人。"},"Pro-подписка":{"en":"Pro subscription","fr":"Abonnement Pro","de":"Pro-Abo","es":"Suscripción Pro","it":"Abbonamento Pro","zh":"Pro 订阅"},"— платный доступ к расширенным возможностям Сервиса на условиях ежемесячного списания.":{"en":"— paid access to the Service’s extended features with monthly charging.","fr":"— accès payant aux fonctions étendues du Service avec prélèvement mensuel.","de":"— kostenpflichtiger Zugang zu den erweiterten Funktionen des Dienstes mit monatlicher Abbuchung.","es":"— acceso de pago a las funciones ampliadas del Servicio con cargo mensual.","it":"— accesso a pagamento alle funzioni avanzate del Servizio con addebito mensile.","zh":"——指以按月扣费方式付费使用服务的扩展功能。"},"Платёжный агент":{"en":"Payment agent","fr":"Agent de paiement","de":"Zahlungsdienstleister","es":"Agente de pagos","it":"Agente di pagamento","zh":"支付代理"},"— сторонняя платёжная организация, обеспечивающая приём платежей (эквайринг) в пользу Правообладателя.":{"en":"— a third-party payment organisation that accepts payments (acquiring) on behalf of the Rights Holder.","fr":"— organisme de paiement tiers assurant l’encaissement des paiements (acquisition) au profit du Titulaire des droits.","de":"— ein externes Zahlungsunternehmen, das Zahlungen (Acquiring) zugunsten des Rechteinhabers entgegennimmt.","es":"— entidad de pagos externa que gestiona el cobro (adquirencia) a favor del Titular de los derechos.","it":"— organizzazione di pagamento terza che gestisce l’incasso dei pagamenti (acquiring) a favore del Titolare dei diritti.","zh":"——指为权利人收取款项（收单）的第三方支付机构。"},"2. Общие положения":{"en":"2. General provisions","fr":"2. Dispositions générales","de":"2. Allgemeine Bestimmungen","es":"2. Disposiciones generales","it":"2. Disposizioni generali","zh":"2. 总则"},"2.1. Настоящая Оферта заключена в соответствии со статьёй 437 Гражданского кодекса Российской Федерации и регулирует отношения между Правообладателем Сервиса HarmonyAI (далее — «Правообладатель») и Пользователем по предоставлению платного доступа к Сервису.":{"en":"2.1. This Offer is made in accordance with Article 437 of the Civil Code of the Russian Federation and governs relations between the Rights Holder of the HarmonyAI Service (the “Rights Holder”) and the User regarding paid access to the Service.","fr":"2.1. La présente Offre est établie conformément à l’article 437 du Code civil de la Fédération de Russie et régit les relations entre le Titulaire des droits du Service HarmonyAI (ci-après le « Titulaire des droits ») et l’Utilisateur concernant l’accès payant au Service.","de":"2.1. Dieses Angebot wird gemäß Artikel 437 des Zivilgesetzbuchs der Russischen Föderation abgegeben und regelt die Beziehungen zwischen dem Rechteinhaber des Dienstes HarmonyAI (nachfolgend „Rechteinhaber“) und dem Nutzer über den kostenpflichtigen Zugang zum Dienst.","es":"2.1. La presente Oferta se formula de conformidad con el artículo 437 del Código Civil de la Federación de Rusia y regula las relaciones entre el Titular de los derechos del Servicio HarmonyAI (en adelante, el «Titular») y el Usuario en cuanto al acceso de pago al Servicio.","it":"2.1. La presente Offerta è formulata ai sensi dell’articolo 437 del Codice civile della Federazione Russa e disciplina i rapporti tra il Titolare dei diritti del Servizio HarmonyAI (di seguito «Titolare») e l’Utente in merito all’accesso a pagamento al Servizio.","zh":"2.1. 本要约依据《俄罗斯联邦民法典》第 437 条订立，调整 HarmonyAI 服务权利人（以下简称“权利人”）与用户之间关于付费使用服务的关系。"},"2.2. Акцептом Оферты в полном объёме является совершение Пользователем платежа за Pro-подписку. С момента акцепта Оферта считается заключённым договором возмездного оказания услуг. Частичный акцепт не допускается.":{"en":"2.2. Full acceptance of the Offer is the User’s payment for the Pro subscription. From the moment of acceptance, the Offer is deemed a concluded contract for the paid provision of services. Partial acceptance is not allowed.","fr":"2.2. L’acceptation intégrale de l’Offre résulte du paiement de l’abonnement Pro par l’Utilisateur. À compter de l’acceptation, l’Offre vaut contrat de prestation de services à titre onéreux. Une acceptation partielle n’est pas admise.","de":"2.2. Als vollständige Annahme des Angebots gilt die Zahlung des Pro-Abos durch den Nutzer. Ab der Annahme gilt das Angebot als geschlossener Vertrag über entgeltliche Dienstleistungen. Eine teilweise Annahme ist nicht zulässig.","es":"2.2. La aceptación íntegra de la Oferta se produce con el pago de la suscripción Pro por parte del Usuario. Desde la aceptación, la Oferta se considera un contrato de prestación de servicios a título oneroso. No se admite la aceptación parcial.","it":"2.2. L’accettazione integrale dell’Offerta avviene con il pagamento dell’abbonamento Pro da parte dell’Utente. Dal momento dell’accettazione l’Offerta si considera un contratto concluso di prestazione di servizi a titolo oneroso. Non è ammessa l’accettazione parziale.","zh":"2.2. 用户支付 Pro 订阅费用即视为完全接受本要约。自接受之时起，本要约即视为已订立的有偿服务合同。不允许部分接受。"},"2.3. Настоящая Оферта является неотъемлемым дополнением":{"en":"2.3. This Offer is an integral addition to the","fr":"2.3. La présente Offre fait partie intégrante des","de":"2.3. Dieses Angebot ist ein untrennbarer Bestandteil der","es":"2.3. La presente Oferta es un complemento inseparable de los","it":"2.3. La presente Offerta costituisce parte integrante dei","zh":"2.3. 本要约是服务的"},"Условий использования":{"en":"Terms of Use","fr":"Conditions d’utilisation","de":"Nutzungsbedingungen","es":"Términos de uso","it":"Termini di utilizzo","zh":"《使用条款》"},"Политики конфиденциальности":{"en":"Privacy Policy","fr":"Politique de confidentialité","de":"Datenschutzerklärung","es":"Política de privacidad","it":"Informativa sulla privacy","zh":"《隐私政策》"},"Сервиса. В вопросах, не урегулированных Офертой, применяются указанные документы.":{"en":"of the Service. Matters not covered by the Offer are governed by those documents.","fr":"du Service. Pour les questions non réglées par l’Offre, ces documents s’appliquent.","de":"des Dienstes. In Fragen, die das Angebot nicht regelt, gelten diese Dokumente.","es":"del Servicio. En las cuestiones no reguladas por la Oferta se aplican dichos documentos.","it":"del Servizio. Per le questioni non disciplinate dall’Offerta si applicano tali documenti.","zh":"的组成部分。本要约未规定的事项，适用上述文件。"},"3. Предмет Оферты":{"en":"3. Subject of the Offer","fr":"3. Objet de l’Offre","de":"3. Gegenstand des Angebots","es":"3. Objeto de la Oferta","it":"3. Oggetto dell’Offerta","zh":"3. 要约标的"},"3.1. Правообладатель обязуется предоставить Пользователю за плату доступ к расширенным возможностям Сервиса (Pro-подписка), а Пользователь обязуется оплатить этот доступ.":{"en":"3.1. The Rights Holder undertakes to provide the User with paid access to the Service’s extended features (the Pro subscription), and the User undertakes to pay for this access.","fr":"3.1. Le Titulaire des droits s’engage à fournir à l’Utilisateur, contre paiement, un accès aux fonctions étendues du Service (abonnement Pro), et l’Utilisateur s’engage à payer cet accès.","de":"3.1. Der Rechteinhaber verpflichtet sich, dem Nutzer gegen Entgelt Zugang zu den erweiterten Funktionen des Dienstes (Pro-Abo) zu gewähren, und der Nutzer verpflichtet sich, diesen Zugang zu bezahlen.","es":"3.1. El Titular se compromete a proporcionar al Usuario, a cambio de un pago, acceso a las funciones ampliadas del Servicio (suscripción Pro), y el Usuario se compromete a pagar dicho acceso.","it":"3.1. Il Titolare si impegna a fornire all’Utente, a pagamento, l’accesso alle funzioni avanzate del Servizio (abbonamento Pro) e l’Utente si impegna a pagare tale accesso.","zh":"3.1. 权利人承诺向用户有偿提供服务扩展功能的访问权限（Pro 订阅），用户承诺为该访问权限付费。"},"3.2. В состав Pro-подписки входят: флагманская модель Dynatos, расширенные уровни размышления (Max и Extra), распознавание мелодий и нотная запись, генерация изображений моделью повышенного качества, приоритетная обработка запросов.":{"en":"3.2. The Pro subscription includes: the flagship Dynatos model, extended thinking levels (Max and Extra), melody recognition and music notation, image generation with a higher-quality model, and priority request processing.","fr":"3.2. L’abonnement Pro comprend : le modèle phare Dynatos, les niveaux de réflexion étendus (Max et Extra), la reconnaissance de mélodies et la notation musicale, la génération d’images par un modèle de meilleure qualité et le traitement prioritaire des requêtes.","de":"3.2. Das Pro-Abo umfasst: das Flaggschiff-Modell Dynatos, erweiterte Denkstufen (Max und Extra), Melodieerkennung und Notenschrift, Bilderzeugung mit einem hochwertigeren Modell sowie bevorzugte Bearbeitung von Anfragen.","es":"3.2. La suscripción Pro incluye: el modelo insignia Dynatos, niveles de razonamiento ampliados (Max y Extra), reconocimiento de melodías y notación musical, generación de imágenes con un modelo de mayor calidad y procesamiento prioritario de solicitudes.","it":"3.2. L’abbonamento Pro comprende: il modello di punta Dynatos, livelli di ragionamento avanzati (Max ed Extra), riconoscimento delle melodie e notazione musicale, generazione di immagini con un modello di qualità superiore e gestione prioritaria delle richieste.","zh":"3.2. Pro 订阅包括：旗舰模型 Dynatos、扩展思考级别（Max 和 Extra）、旋律识别与记谱、使用更高质量模型生成图片，以及请求优先处理。"},"3.3. Подписка действует один календарный месяц с момента оплаты (далее — «Оплаченный период») и продлевается в порядке раздела 6 настоящей Оферты.":{"en":"3.3. The subscription is valid for one calendar month from the moment of payment (the “Paid Period”) and is renewed as set out in section 6 of this Offer.","fr":"3.3. L’abonnement est valable un mois calendaire à compter du paiement (ci-après la « Période payée ») et se renouvelle selon les modalités de la section 6 de la présente Offre.","de":"3.3. Das Abo gilt einen Kalendermonat ab der Zahlung (nachfolgend „bezahlter Zeitraum“) und verlängert sich gemäß Abschnitt 6 dieses Angebots.","es":"3.3. La suscripción es válida durante un mes natural desde el pago (en adelante, el «Periodo pagado») y se renueva según lo previsto en la sección 6 de la presente Oferta.","it":"3.3. L’abbonamento è valido per un mese di calendario dal pagamento (di seguito «Periodo pagato») e si rinnova secondo quanto previsto dalla sezione 6 della presente Offerta.","zh":"3.3. 订阅自付款之日起有效期为一个自然月（以下简称“已付期间”），并按本要约第 6 节的规定续期。"},"4. Лимиты и порядок оказания услуг":{"en":"4. Limits and procedure for providing services","fr":"4. Limites et modalités de fourniture des services","de":"4. Limits und Erbringung der Leistungen","es":"4. Límites y forma de prestación de los servicios","it":"4. Limiti e modalità di prestazione dei servizi","zh":"4. 额度与服务提供方式"},"4.1. Сообщения и генерации в рамках Pro-подписки не ограничены фиксированным количеством.":{"en":"4.1. Messages and generations under the Pro subscription are not limited to a fixed number.","fr":"4.1. Les messages et générations dans le cadre de l’abonnement Pro ne sont pas limités à un nombre fixe.","de":"4.1. Nachrichten und Generierungen im Rahmen des Pro-Abos sind nicht auf eine feste Anzahl begrenzt.","es":"4.1. Los mensajes y generaciones de la suscripción Pro no están limitados a una cantidad fija.","it":"4.1. I messaggi e le generazioni nell’ambito dell’abbonamento Pro non sono limitati a un numero fisso.","zh":"4.1. Pro 订阅下的消息与生成不设固定数量限制。"},"4.2. При этом Сервис применяет автоматическую защиту от злоупотребления: при очень частых запросах подряд (например, более 25 сообщений в течение трёх минут) генерация может быть временно приостановлена на несколько минут. Также действует очень высокий суточный предел защиты от злоупотребления; если Пользователь достиг его при обычном использовании, Сервис рекомендует обратиться в поддержку.":{"en":"4.2. At the same time, the Service applies automatic abuse protection: with very frequent requests in a row (for example, more than 25 messages within three minutes), generation may be temporarily paused for a few minutes. A very high daily abuse-protection ceiling also applies; if the User reaches it during normal use, the Service recommends contacting support.","fr":"4.2. Le Service applique toutefois une protection automatique contre les abus : en cas de requêtes très fréquentes (par exemple plus de 25 messages en trois minutes), la génération peut être suspendue quelques minutes. Un plafond journalier de protection très élevé s’applique également ; si l’Utilisateur l’atteint lors d’un usage normal, le Service recommande de contacter l’assistance.","de":"4.2. Dabei wendet der Dienst einen automatischen Missbrauchsschutz an: Bei sehr häufigen Anfragen hintereinander (z. B. mehr als 25 Nachrichten innerhalb von drei Minuten) kann die Generierung für einige Minuten pausiert werden. Außerdem gilt eine sehr hohe tägliche Schutzgrenze; erreicht der Nutzer sie bei normaler Nutzung, empfiehlt der Dienst, sich an den Support zu wenden.","es":"4.2. No obstante, el Servicio aplica una protección automática contra abusos: con solicitudes muy seguidas (por ejemplo, más de 25 mensajes en tres minutos), la generación puede pausarse unos minutos. También rige un límite diario de protección muy alto; si el Usuario lo alcanza con un uso normal, el Servicio recomienda contactar con soporte.","it":"4.2. Il Servizio applica comunque una protezione automatica dagli abusi: in caso di richieste molto ravvicinate (ad esempio più di 25 messaggi in tre minuti) la generazione può essere sospesa per alcuni minuti. È inoltre previsto un limite giornaliero di protezione molto elevato; se l’Utente lo raggiunge con un uso normale, il Servizio consiglia di contattare l’assistenza.","zh":"4.2. 同时，服务启用自动防滥用保护：若连续请求过于频繁（例如三分钟内超过 25 条消息），生成可能会暂停几分钟。此外还设有非常高的每日防滥用上限；如用户在正常使用中达到该上限，建议联系客服。"},"4.3. Защита от злоупотребления направлена на обеспечение стабильной работы Сервиса для всех Пользователей и не является ограничением объёма услуг при добросовестном использовании.":{"en":"4.3. Abuse protection is intended to ensure stable operation of the Service for all Users and is not a limitation on the volume of services for good-faith use.","fr":"4.3. La protection contre les abus vise à garantir un fonctionnement stable du Service pour tous les Utilisateurs et ne constitue pas une limitation du volume de services en cas d’usage de bonne foi.","de":"4.3. Der Missbrauchsschutz dient dem stabilen Betrieb des Dienstes für alle Nutzer und stellt bei redlicher Nutzung keine Begrenzung des Leistungsumfangs dar.","es":"4.3. La protección contra abusos tiene por objeto garantizar el funcionamiento estable del Servicio para todos los Usuarios y no limita el volumen de servicios en caso de uso de buena fe.","it":"4.3. La protezione dagli abusi mira a garantire il funzionamento stabile del Servizio per tutti gli Utenti e non costituisce una limitazione del volume dei servizi in caso di uso in buona fede.","zh":"4.3. 防滥用保护旨在确保服务对所有用户稳定运行，在善意使用的情况下不构成对服务量的限制。"},"4.4. Для бесплатного тарифа действуют общий лимит в каждом 5-часовом окне и общий месячный лимит. В разделе «Лимиты» отображается процент использованного объёма каждого окна. После исчерпания лимита генерация приостанавливается до его обновления либо до оформления Pro-подписки.":{"en":"4.4. The free plan has a shared limit in each 5-hour window and a shared monthly limit. The “Limits” section shows the percentage used of each window. Once a limit is exhausted, generation pauses until it resets or until a Pro subscription is taken out.","fr":"4.4. La formule gratuite comporte une limite commune par fenêtre de 5 heures et une limite mensuelle commune. La rubrique « Limites » affiche le pourcentage utilisé de chaque fenêtre. Une fois la limite atteinte, la génération est suspendue jusqu’à son renouvellement ou jusqu’à la souscription à l’abonnement Pro.","de":"4.4. Für den kostenlosen Tarif gelten ein gemeinsames Limit in jedem 5-Stunden-Fenster und ein gemeinsames Monatslimit. Im Bereich „Limits“ wird angezeigt, wie viel Prozent jedes Fensters verbraucht sind. Nach Ausschöpfung des Limits pausiert die Generierung bis zur Erneuerung oder bis zum Abschluss eines Pro-Abos.","es":"4.4. El plan gratuito tiene un límite común en cada ventana de 5 horas y un límite mensual común. La sección «Límites» muestra el porcentaje consumido de cada ventana. Al agotarse el límite, la generación se pausa hasta que se renueve o hasta contratar la suscripción Pro.","it":"4.4. Il piano gratuito prevede un limite comune per ogni finestra di 5 ore e un limite mensile comune. La sezione «Limiti» mostra la percentuale utilizzata di ogni finestra. Esaurito il limite, la generazione si sospende fino al rinnovo o fino all’attivazione dell’abbonamento Pro.","zh":"4.4. 免费套餐在每个 5 小时窗口内设有总额度，并设有每月总额度。“额度”栏目显示每个窗口的已用百分比。额度用完后，生成将暂停，直至额度重置或开通 Pro 订阅。"},"5. Стоимость и порядок оплаты":{"en":"5. Price and payment procedure","fr":"5. Prix et modalités de paiement","de":"5. Preis und Zahlungsweise","es":"5. Precio y forma de pago","it":"5. Prezzo e modalità di pagamento","zh":"5. 价格与支付方式"},"5.1. Стоимость Pro-подписки — 299 (двести девяносто девять) рублей за один Оплаченный период. Правообладатель вправе изменять стоимость для новых оплаченных периодов, уведомив Пользователя не позднее чем за 7 дней до окончания текущего периода (см. раздел 6).":{"en":"5.1. The price of the Pro subscription is 299 (two hundred and ninety-nine) rubles per Paid Period. The Rights Holder may change the price for new paid periods by notifying the User no later than 7 days before the end of the current period (see section 6).","fr":"5.1. Le prix de l’abonnement Pro est de 299 (deux cent quatre-vingt-dix-neuf) roubles par Période payée. Le Titulaire des droits peut modifier le prix pour les nouvelles périodes en informant l’Utilisateur au plus tard 7 jours avant la fin de la période en cours (voir section 6).","de":"5.1. Der Preis des Pro-Abos beträgt 299 (zweihundertneunundneunzig) Rubel pro bezahltem Zeitraum. Der Rechteinhaber kann den Preis für neue Zeiträume ändern, wenn er den Nutzer spätestens 7 Tage vor Ende des laufenden Zeitraums informiert (siehe Abschnitt 6).","es":"5.1. El precio de la suscripción Pro es de 299 (doscientos noventa y nueve) rublos por Periodo pagado. El Titular puede modificar el precio para nuevos periodos avisando al Usuario con al menos 7 días de antelación al fin del periodo en curso (véase la sección 6).","it":"5.1. Il prezzo dell’abbonamento Pro è di 299 (duecentonovantanove) rubli per Periodo pagato. Il Titolare può modificare il prezzo per i nuovi periodi informando l’Utente almeno 7 giorni prima della fine del periodo in corso (vedi sezione 6).","zh":"5.1. Pro 订阅价格为每个已付期间 299（二百九十九）卢布。权利人有权调整新付费期间的价格，但须在当前期间结束前至少 7 天通知用户（见第 6 节）。"},"5.2. Оплата производится Пользователем в рублях Российской Федерации банковской картой либо иным способом через Платёжного агента. Моментом оплаты считается момент подтверждения платежа Платёжным агентом.":{"en":"5.2. The User pays in rubles of the Russian Federation by bank card or another method via the Payment agent. The moment of payment is the moment the payment is confirmed by the Payment agent.","fr":"5.2. L’Utilisateur paie en roubles de la Fédération de Russie par carte bancaire ou par un autre moyen via l’Agent de paiement. Le paiement est réputé effectué au moment de sa confirmation par l’Agent de paiement.","de":"5.2. Der Nutzer zahlt in Rubel der Russischen Föderation per Bankkarte oder auf andere Weise über den Zahlungsdienstleister. Als Zahlungszeitpunkt gilt die Bestätigung der Zahlung durch den Zahlungsdienstleister.","es":"5.2. El Usuario paga en rublos de la Federación de Rusia con tarjeta bancaria u otro medio a través del Agente de pagos. Se considera momento del pago el de su confirmación por el Agente de pagos.","it":"5.2. L’Utente paga in rubli della Federazione Russa con carta bancaria o con altro metodo tramite l’Agente di pagamento. Il momento del pagamento è quello della conferma da parte dell’Agente di pagamento.","zh":"5.2. 用户通过支付代理以俄罗斯联邦卢布、使用银行卡或其他方式付款。付款时间以支付代理确认付款的时间为准。"},"5.3. Правообладатель не получает и не хранит полные данные банковских карт Пользователя: их обработка осуществляется Платёжным агентом в соответствии с требованиями платёжных систем и законодательства РФ.":{"en":"5.3. The Rights Holder does not receive or store the User’s full bank card details: they are processed by the Payment agent in accordance with the requirements of payment systems and the legislation of the Russian Federation.","fr":"5.3. Le Titulaire des droits ne reçoit ni ne conserve les données complètes des cartes bancaires de l’Utilisateur : elles sont traitées par l’Agent de paiement conformément aux exigences des systèmes de paiement et à la législation de la Fédération de Russie.","de":"5.3. Der Rechteinhaber erhält und speichert keine vollständigen Bankkartendaten des Nutzers: Diese verarbeitet der Zahlungsdienstleister gemäß den Anforderungen der Zahlungssysteme und der Gesetzgebung der Russischen Föderation.","es":"5.3. El Titular no recibe ni almacena los datos completos de las tarjetas bancarias del Usuario: los trata el Agente de pagos conforme a los requisitos de los sistemas de pago y la legislación de la Federación de Rusia.","it":"5.3. Il Titolare non riceve né conserva i dati completi delle carte bancarie dell’Utente: sono trattati dall’Agente di pagamento secondo i requisiti dei circuiti di pagamento e la legislazione della Federazione Russa.","zh":"5.3. 权利人不获取也不保存用户银行卡的完整信息：这些信息由支付代理依照支付系统要求和俄罗斯联邦法律处理。"},"5.4. Pro-подписка и баланс API-доступа являются независимыми: подписка не начисляет баланс, баланс не включает Pro-подписку.":{"en":"5.4. The Pro subscription and the API access balance are independent: the subscription does not add balance, and the balance does not include the Pro subscription.","fr":"5.4. L’abonnement Pro et le solde d’accès à l’API sont indépendants : l’abonnement ne crédite pas le solde et le solde n’inclut pas l’abonnement Pro.","de":"5.4. Pro-Abo und API-Guthaben sind unabhängig: Das Abo lädt kein Guthaben auf, und das Guthaben enthält kein Pro-Abo.","es":"5.4. La suscripción Pro y el saldo de acceso a la API son independientes: la suscripción no añade saldo y el saldo no incluye la suscripción Pro.","it":"5.4. L’abbonamento Pro e il saldo di accesso all’API sono indipendenti: l’abbonamento non accredita saldo e il saldo non include l’abbonamento Pro.","zh":"5.4. Pro 订阅与 API 访问余额相互独立：订阅不增加余额，余额也不包含 Pro 订阅。"},"6. Автопродление и изменение стоимости":{"en":"6. Auto-renewal and price changes","fr":"6. Renouvellement automatique et modification du prix","de":"6. Automatische Verlängerung und Preisänderung","es":"6. Renovación automática y cambio de precio","it":"6. Rinnovo automatico e modifica del prezzo","zh":"6. 自动续费与价格变更"},"6.1. Подписка продлевается автоматически на очередной Оплаченный период, если Пользователь не отменил её до даты очередного списания. Продление происходит списанием стоимости, действующей на момент продления.":{"en":"6.1. The subscription is renewed automatically for the next Paid Period unless the User cancels it before the next charge date. Renewal is made by charging the price in effect at the time of renewal.","fr":"6.1. L’abonnement est renouvelé automatiquement pour la Période payée suivante si l’Utilisateur ne l’a pas résilié avant la date du prochain prélèvement. Le renouvellement s’effectue au prix en vigueur à ce moment.","de":"6.1. Das Abo verlängert sich automatisch um den nächsten bezahlten Zeitraum, sofern der Nutzer es nicht vor dem nächsten Abbuchungstermin kündigt. Die Verlängerung erfolgt zum dann gültigen Preis.","es":"6.1. La suscripción se renueva automáticamente por el siguiente Periodo pagado si el Usuario no la cancela antes de la fecha del siguiente cargo. La renovación se cobra al precio vigente en ese momento.","it":"6.1. L’abbonamento si rinnova automaticamente per il Periodo pagato successivo se l’Utente non lo annulla prima della data del prossimo addebito. Il rinnovo avviene al prezzo in vigore in quel momento.","zh":"6.1. 如用户未在下一次扣费日前取消，订阅将自动续订下一个已付期间，按续费时的有效价格扣费。"},"6.2. Пользователь может отменить подписку в любой момент в настройках Сервиса или через поддержку. При отмене доступ к Pro-функциям сохраняется до конца уже оплаченного периода, после чего прекращается.":{"en":"6.2. The User may cancel the subscription at any time in the Service settings or through support. Upon cancellation, access to Pro features remains until the end of the already paid period and then ends.","fr":"6.2. L’Utilisateur peut résilier l’abonnement à tout moment dans les paramètres du Service ou via l’assistance. En cas de résiliation, l’accès aux fonctions Pro est maintenu jusqu’à la fin de la période déjà payée, puis prend fin.","de":"6.2. Der Nutzer kann das Abo jederzeit in den Einstellungen des Dienstes oder über den Support kündigen. Nach der Kündigung bleibt der Zugang zu Pro-Funktionen bis zum Ende des bereits bezahlten Zeitraums bestehen und endet dann.","es":"6.2. El Usuario puede cancelar la suscripción en cualquier momento en la configuración del Servicio o a través de soporte. Tras la cancelación, el acceso a las funciones Pro se mantiene hasta el final del periodo ya pagado y después finaliza.","it":"6.2. L’Utente può annullare l’abbonamento in qualsiasi momento nelle impostazioni del Servizio o tramite l’assistenza. In caso di annullamento, l’accesso alle funzioni Pro resta attivo fino alla fine del periodo già pagato e poi cessa.","zh":"6.2. 用户可随时在服务设置中或通过客服取消订阅。取消后，Pro 功能的访问权限保留至已付期间结束，之后终止。"},"6.3. При изменении стоимости Правообладатель направляет Пользователю уведомление (в интерфейсе Сервиса и/или по электронной почте) не позднее чем за 7 дней до даты очередного списания. Продолжение использования подписки после вступления новой стоимости в силу означает согласие Пользователя с новой ценой; при несогласии Пользователь вправе отменить подписку.":{"en":"6.3. When the price changes, the Rights Holder sends the User a notice (in the Service interface and/or by email) no later than 7 days before the next charge date. Continued use of the subscription after the new price takes effect means the User agrees to the new price; if the User disagrees, they may cancel the subscription.","fr":"6.3. En cas de modification du prix, le Titulaire des droits adresse un avis à l’Utilisateur (dans l’interface du Service et/ou par e-mail) au plus tard 7 jours avant la date du prochain prélèvement. La poursuite de l’abonnement après l’entrée en vigueur du nouveau prix vaut acceptation de celui-ci ; en cas de désaccord, l’Utilisateur peut résilier l’abonnement.","de":"6.3. Bei einer Preisänderung sendet der Rechteinhaber dem Nutzer spätestens 7 Tage vor dem nächsten Abbuchungstermin eine Mitteilung (in der Oberfläche des Dienstes und/oder per E-Mail). Die weitere Nutzung des Abos nach Inkrafttreten des neuen Preises gilt als Zustimmung; ist der Nutzer nicht einverstanden, kann er das Abo kündigen.","es":"6.3. Si cambia el precio, el Titular envía al Usuario un aviso (en la interfaz del Servicio y/o por correo electrónico) con al menos 7 días de antelación a la fecha del siguiente cargo. Seguir usando la suscripción tras la entrada en vigor del nuevo precio implica aceptarlo; si el Usuario no está de acuerdo, puede cancelar la suscripción.","it":"6.3. In caso di modifica del prezzo, il Titolare invia all’Utente una notifica (nell’interfaccia del Servizio e/o via email) almeno 7 giorni prima della data del prossimo addebito. Continuare a usare l’abbonamento dopo l’entrata in vigore del nuovo prezzo equivale ad accettarlo; in caso di disaccordo l’Utente può annullare l’abbonamento.","zh":"6.3. 价格变更时，权利人会在下一次扣费日前至少 7 天（通过服务界面和/或电子邮件）通知用户。新价格生效后继续使用订阅，即视为用户同意新价格；如不同意，用户可取消订阅。"},"7. Возвраты":{"en":"7. Refunds","fr":"7. Remboursements","de":"7. Rückerstattungen","es":"7. Reembolsos","it":"7. Rimborsi","zh":"7. 退款"},"7.1. По общему правилу оплата за текущий Оплаченный период не возвращается, поскольку услуги оказываются в полном объёме в течение всего периода.":{"en":"7.1. As a general rule, payment for the current Paid Period is not refunded, since the services are provided in full throughout the period.","fr":"7.1. En règle générale, le paiement de la Période payée en cours n’est pas remboursé, les services étant fournis intégralement pendant toute la période.","de":"7.1. Grundsätzlich wird die Zahlung für den laufenden bezahlten Zeitraum nicht erstattet, da die Leistungen während des gesamten Zeitraums vollständig erbracht werden.","es":"7.1. Como norma general, el pago del Periodo pagado en curso no se reembolsa, ya que los servicios se prestan íntegramente durante todo el periodo.","it":"7.1. Di norma il pagamento del Periodo pagato in corso non viene rimborsato, poiché i servizi sono forniti integralmente per tutto il periodo.","zh":"7.1. 一般情况下，当前已付期间的费用不予退还，因为服务在整个期间内均已完整提供。"},"7.2. Возврат возможен в случаях: невозможности оказания услуг по вине Правообладателя; ошибочного двойного списания; технической ошибки, приведшей к оплате без предоставления доступа.":{"en":"7.2. A refund is possible if: the services could not be provided through the fault of the Rights Holder; there was an erroneous double charge; a technical error led to payment without access being granted.","fr":"7.2. Un remboursement est possible en cas : d’impossibilité de fournir les services par la faute du Titulaire des droits ; de double prélèvement erroné ; d’erreur technique ayant entraîné un paiement sans accès.","de":"7.2. Eine Erstattung ist möglich, wenn: die Leistungen durch Verschulden des Rechteinhabers nicht erbracht werden konnten; versehentlich doppelt abgebucht wurde; ein technischer Fehler zu einer Zahlung ohne Zugang geführt hat.","es":"7.2. El reembolso es posible en caso de: imposibilidad de prestar los servicios por culpa del Titular; doble cargo por error; error técnico que haya provocado un pago sin acceso.","it":"7.2. Il rimborso è possibile in caso di: impossibilità di fornire i servizi per colpa del Titolare; doppio addebito per errore; errore tecnico che ha comportato un pagamento senza accesso.","zh":"7.2. 以下情况可以退款：因权利人原因无法提供服务；错误重复扣费；技术错误导致已付款但未获得访问权限。"},"7.3. Заявка на возврат направляется на почту":{"en":"7.3. A refund request is sent to the email","fr":"7.3. La demande de remboursement est envoyée à l’adresse","de":"7.3. Ein Erstattungsantrag wird an die E-Mail","es":"7.3. La solicitud de reembolso se envía al correo","it":"7.3. La richiesta di rimborso va inviata all’indirizzo","zh":"7.3. 退款申请请发送至邮箱"},"с указанием даты платежа и описания проблемы. Срок рассмотрения — до 10 рабочих дней. Возврат осуществляется на тот же способ оплаты, которым был произведён платёж.":{"en":"stating the payment date and a description of the problem. Review takes up to 10 business days. The refund is made to the same payment method used for the payment.","fr":"en indiquant la date du paiement et une description du problème. Le délai d’examen est de 10 jours ouvrés maximum. Le remboursement s’effectue sur le moyen de paiement utilisé.","de":"mit Angabe des Zahlungsdatums und einer Problembeschreibung gesendet. Die Bearbeitung dauert bis zu 10 Werktage. Die Erstattung erfolgt auf das für die Zahlung genutzte Zahlungsmittel.","es":"indicando la fecha del pago y una descripción del problema. El plazo de revisión es de hasta 10 días hábiles. El reembolso se realiza al mismo medio de pago utilizado.","it":"indicando la data del pagamento e una descrizione del problema. L’esame richiede fino a 10 giorni lavorativi. Il rimborso avviene sullo stesso metodo di pagamento utilizzato.","zh":"，注明付款日期并说明问题。审核期限最长 10 个工作日。退款将原路退回至付款时使用的支付方式。"},"8. Права и обязанности сторон":{"en":"8. Rights and obligations of the parties","fr":"8. Droits et obligations des parties","de":"8. Rechte und Pflichten der Parteien","es":"8. Derechos y obligaciones de las partes","it":"8. Diritti e obblighi delle parti","zh":"8. 双方的权利与义务"},"8.1. Правообладатель обязуется: предоставлять доступ к Pro-функциям в течение Оплаченного периода; обеспечивать работоспособность Сервиса; не ограничивать добросовестное использование, кроме случаев, предусмотренных разделом 4.":{"en":"8.1. The Rights Holder undertakes to: provide access to Pro features during the Paid Period; keep the Service operational; not restrict good-faith use except as provided in section 4.","fr":"8.1. Le Titulaire des droits s’engage à : fournir l’accès aux fonctions Pro pendant la Période payée ; assurer le bon fonctionnement du Service ; ne pas restreindre un usage de bonne foi, sauf dans les cas prévus à la section 4.","de":"8.1. Der Rechteinhaber verpflichtet sich: während des bezahlten Zeitraums Zugang zu den Pro-Funktionen zu gewähren; die Funktionsfähigkeit des Dienstes sicherzustellen; redliche Nutzung nicht einzuschränken, außer in den in Abschnitt 4 genannten Fällen.","es":"8.1. El Titular se compromete a: proporcionar acceso a las funciones Pro durante el Periodo pagado; garantizar el funcionamiento del Servicio; no limitar el uso de buena fe, salvo en los casos previstos en la sección 4.","it":"8.1. Il Titolare si impegna a: fornire l’accesso alle funzioni Pro durante il Periodo pagato; garantire il funzionamento del Servizio; non limitare l’uso in buona fede, salvo nei casi previsti dalla sezione 4.","zh":"8.1. 权利人承诺：在已付期间内提供 Pro 功能的访问权限；保障服务正常运行；除第 4 节规定的情形外，不限制善意使用。"},"8.2. Правообладатель вправе: временно приостанавливать работу Сервиса для технического обслуживания; изменять состав Pro-функций, не ухудшая существенно их объём для Пользователя; прекращать подписку Пользователю, нарушившему Условия использования.":{"en":"8.2. The Rights Holder may: temporarily suspend the Service for maintenance; change the set of Pro features without substantially reducing their scope for the User; terminate the subscription of a User who has violated the Terms of Use.","fr":"8.2. Le Titulaire des droits peut : suspendre temporairement le Service pour maintenance ; modifier la composition des fonctions Pro sans en réduire sensiblement l’étendue pour l’Utilisateur ; mettre fin à l’abonnement d’un Utilisateur ayant enfreint les Conditions d’utilisation.","de":"8.2. Der Rechteinhaber ist berechtigt: den Dienst für Wartungsarbeiten vorübergehend auszusetzen; den Umfang der Pro-Funktionen zu ändern, ohne ihn für den Nutzer wesentlich zu verschlechtern; das Abo eines Nutzers zu beenden, der gegen die Nutzungsbedingungen verstoßen hat.","es":"8.2. El Titular tiene derecho a: suspender temporalmente el Servicio por mantenimiento; modificar las funciones Pro sin reducir sustancialmente su alcance para el Usuario; dar por terminada la suscripción del Usuario que haya incumplido los Términos de uso.","it":"8.2. Il Titolare ha diritto di: sospendere temporaneamente il Servizio per manutenzione; modificare l’insieme delle funzioni Pro senza ridurne sostanzialmente la portata per l’Utente; interrompere l’abbonamento dell’Utente che abbia violato i Termini di utilizzo.","zh":"8.2. 权利人有权：为技术维护暂停服务；在不实质减少用户可用范围的前提下调整 Pro 功能组成；终止违反《使用条款》用户的订阅。"},"8.3. Пользователь обязуется: оплачивать услуги в установленном порядке; не передавать доступ к аккаунту третьим лицам; не использовать Сервис для обхода защит и генерации противоправного контента.":{"en":"8.3. The User undertakes to: pay for the services as established; not transfer access to the account to third parties; not use the Service to bypass protections or generate unlawful content.","fr":"8.3. L’Utilisateur s’engage à : payer les services selon les modalités prévues ; ne pas transmettre l’accès à son compte à des tiers ; ne pas utiliser le Service pour contourner des protections ou générer un contenu illicite.","de":"8.3. Der Nutzer verpflichtet sich: die Leistungen ordnungsgemäß zu bezahlen; den Kontozugang nicht an Dritte weiterzugeben; den Dienst nicht zur Umgehung von Schutzmaßnahmen oder zur Erzeugung rechtswidriger Inhalte zu nutzen.","es":"8.3. El Usuario se compromete a: pagar los servicios en la forma establecida; no ceder el acceso a la cuenta a terceros; no usar el Servicio para eludir protecciones ni generar contenido ilícito.","it":"8.3. L’Utente si impegna a: pagare i servizi secondo le modalità previste; non cedere l’accesso all’account a terzi; non usare il Servizio per aggirare le protezioni o generare contenuti illeciti.","zh":"8.3. 用户承诺：按规定方式支付服务费用；不将账户访问权转让给第三方；不利用服务规避保护措施或生成违法内容。"},"9. Ограничение ответственности":{"en":"9. Limitation of liability","fr":"9. Limitation de responsabilité","de":"9. Haftungsbeschränkung","es":"9. Limitación de responsabilidad","it":"9. Limitazione di responsabilità","zh":"9. 责任限制"},"9.1. Сервис предоставляется «как есть». Ответы моделей ИИ носят справочный характер и могут содержать неточности; Правообладатель не гарантирует применимость результатов для конкретных целей.":{"en":"9.1. The Service is provided “as is”. AI model answers are for reference only and may contain inaccuracies; the Rights Holder does not guarantee that the results are suitable for specific purposes.","fr":"9.1. Le Service est fourni « en l’état ». Les réponses des modèles d’IA ont une valeur indicative et peuvent contenir des inexactitudes ; le Titulaire des droits ne garantit pas leur adéquation à des fins particulières.","de":"9.1. Der Dienst wird „wie besehen“ bereitgestellt. Antworten der KI-Modelle dienen nur zur Information und können Ungenauigkeiten enthalten; der Rechteinhaber garantiert nicht, dass die Ergebnisse für bestimmte Zwecke geeignet sind.","es":"9.1. El Servicio se presta «tal cual». Las respuestas de los modelos de IA tienen carácter orientativo y pueden contener imprecisiones; el Titular no garantiza su idoneidad para fines concretos.","it":"9.1. Il Servizio è fornito «così com’è». Le risposte dei modelli di IA hanno carattere indicativo e possono contenere imprecisioni; il Titolare non garantisce che i risultati siano adatti a scopi specifici.","zh":"9.1. 服务按“现状”提供。AI 模型的回答仅供参考，可能存在不准确之处；权利人不保证结果适用于特定用途。"},"9.2. Правообладатель не несёт ответственности за упущенную выгоду, потерю данных или иные косвенные убытки Пользователя, возникшие в результате использования Сервиса.":{"en":"9.2. The Rights Holder is not liable for lost profits, data loss or other indirect losses of the User arising from use of the Service.","fr":"9.2. Le Titulaire des droits n’est pas responsable du manque à gagner, de la perte de données ou d’autres préjudices indirects subis par l’Utilisateur du fait de l’utilisation du Service.","de":"9.2. Der Rechteinhaber haftet nicht für entgangenen Gewinn, Datenverlust oder sonstige mittelbare Schäden des Nutzers infolge der Nutzung des Dienstes.","es":"9.2. El Titular no responde del lucro cesante, la pérdida de datos ni otros daños indirectos del Usuario derivados del uso del Servicio.","it":"9.2. Il Titolare non risponde del mancato guadagno, della perdita di dati o di altri danni indiretti subiti dall’Utente a seguito dell’uso del Servizio.","zh":"9.2. 对于用户因使用服务而产生的利润损失、数据丢失或其他间接损失，权利人不承担责任。"},"9.3. Совокупная ответственность Правообладателя ограничена суммой, фактически уплаченной Пользователем за последний Оплаченный период.":{"en":"9.3. The Rights Holder’s total liability is limited to the amount actually paid by the User for the last Paid Period.","fr":"9.3. La responsabilité totale du Titulaire des droits est limitée au montant effectivement payé par l’Utilisateur pour la dernière Période payée.","de":"9.3. Die Gesamthaftung des Rechteinhabers ist auf den Betrag beschränkt, den der Nutzer für den letzten bezahlten Zeitraum tatsächlich gezahlt hat.","es":"9.3. La responsabilidad total del Titular se limita al importe efectivamente pagado por el Usuario por el último Periodo pagado.","it":"9.3. La responsabilità complessiva del Titolare è limitata all’importo effettivamente pagato dall’Utente per l’ultimo Periodo pagato.","zh":"9.3. 权利人的全部责任以用户为最近一个已付期间实际支付的金额为限。"},"10. Срок действия и расторжение":{"en":"10. Term and termination","fr":"10. Durée et résiliation","de":"10. Laufzeit und Beendigung","es":"10. Vigencia y resolución","it":"10. Durata e risoluzione","zh":"10. 有效期与终止"},"10.1. Оферта вступает в силу с даты публикации и действует до её отзыва Правообладателем.":{"en":"10.1. The Offer takes effect from the date of publication and remains valid until it is withdrawn by the Rights Holder.","fr":"10.1. L’Offre entre en vigueur à la date de sa publication et reste valable jusqu’à son retrait par le Titulaire des droits.","de":"10.1. Das Angebot tritt mit dem Datum der Veröffentlichung in Kraft und gilt bis zu seinem Widerruf durch den Rechteinhaber.","es":"10.1. La Oferta entra en vigor en la fecha de su publicación y es válida hasta que el Titular la retire.","it":"10.1. L’Offerta entra in vigore dalla data di pubblicazione ed è valida fino alla sua revoca da parte del Titolare.","zh":"10.1. 本要约自发布之日起生效，在权利人撤回前持续有效。"},"10.2. Правообладатель вправе отозвать Оферту в любой момент. Отзыв не прекращает действие договора в отношении уже оплаченных периодов: доступ предоставляется до их окончания.":{"en":"10.2. The Rights Holder may withdraw the Offer at any time. Withdrawal does not terminate the contract for periods already paid: access is provided until they end.","fr":"10.2. Le Titulaire des droits peut retirer l’Offre à tout moment. Le retrait ne met pas fin au contrat pour les périodes déjà payées : l’accès est fourni jusqu’à leur terme.","de":"10.2. Der Rechteinhaber kann das Angebot jederzeit widerrufen. Der Widerruf beendet den Vertrag für bereits bezahlte Zeiträume nicht: Der Zugang wird bis zu deren Ende gewährt.","es":"10.2. El Titular puede retirar la Oferta en cualquier momento. La retirada no pone fin al contrato respecto de los periodos ya pagados: el acceso se mantiene hasta su finalización.","it":"10.2. Il Titolare può revocare l’Offerta in qualsiasi momento. La revoca non fa cessare il contratto per i periodi già pagati: l’accesso è garantito fino alla loro scadenza.","zh":"10.2. 权利人可随时撤回要约。撤回不影响已付期间的合同效力：访问权限将保留至这些期间结束。"},"10.3. Договор между Пользователем и Правообладателем прекращается с истечением последнего оплаченного периода после отмены подписки либо при удалении аккаунта Пользователем.":{"en":"10.3. The contract between the User and the Rights Holder ends upon expiry of the last paid period after the subscription is cancelled, or when the User deletes their account.","fr":"10.3. Le contrat entre l’Utilisateur et le Titulaire des droits prend fin à l’expiration de la dernière période payée après résiliation de l’abonnement, ou lors de la suppression du compte par l’Utilisateur.","de":"10.3. Der Vertrag zwischen Nutzer und Rechteinhaber endet mit Ablauf des letzten bezahlten Zeitraums nach Kündigung des Abos oder mit der Löschung des Kontos durch den Nutzer.","es":"10.3. El contrato entre el Usuario y el Titular finaliza al expirar el último periodo pagado tras la cancelación de la suscripción o cuando el Usuario elimina su cuenta.","it":"10.3. Il contratto tra l’Utente e il Titolare cessa alla scadenza dell’ultimo periodo pagato dopo l’annullamento dell’abbonamento oppure con l’eliminazione dell’account da parte dell’Utente.","zh":"10.3. 用户与权利人之间的合同在取消订阅后最后一个已付期间届满时终止，或在用户删除账户时终止。"},"11. Реквизиты и контакты":{"en":"11. Details and contacts","fr":"11. Coordonnées et contacts","de":"11. Angaben und Kontakt","es":"11. Datos y contactos","it":"11. Dati e contatti","zh":"11. 主体信息与联系方式"},"Правообладатель: Сервис HarmonyAI.":{"en":"Rights Holder: HarmonyAI Service.","fr":"Titulaire des droits : Service HarmonyAI.","de":"Rechteinhaber: Dienst HarmonyAI.","es":"Titular de los derechos: Servicio HarmonyAI.","it":"Titolare dei diritti: Servizio HarmonyAI.","zh":"权利人：HarmonyAI 服务。"},"ИНН 781455842468.":{"en":"Taxpayer ID (INN) 781455842468.","fr":"INN (identifiant fiscal) 781455842468.","de":"INN (Steuernummer) 781455842468.","es":"INN (número fiscal) 781455842468.","it":"INN (codice fiscale) 781455842468.","zh":"纳税人识别号（INN）781455842468。"},"Telegram-поддержка:":{"en":"Telegram support:","fr":"Assistance Telegram :","de":"Telegram-Support:","es":"Soporte en Telegram:","it":"Assistenza Telegram:","zh":"Telegram 客服："},"12. Применимое право":{"en":"12. Applicable law","fr":"12. Droit applicable","de":"12. Anwendbares Recht","es":"12. Legislación aplicable","it":"12. Legge applicabile","zh":"12. 适用法律"},"12.1. К отношениям сторон применяется законодательство Российской Федерации.":{"en":"12.1. Relations between the parties are governed by the legislation of the Russian Federation.","fr":"12.1. Les relations entre les parties sont régies par la législation de la Fédération de Russie.","de":"12.1. Für die Beziehungen der Parteien gilt das Recht der Russischen Föderation.","es":"12.1. Las relaciones entre las partes se rigen por la legislación de la Federación de Rusia.","it":"12.1. I rapporti tra le parti sono disciplinati dalla legislazione della Federazione Russa.","zh":"12.1. 双方关系适用俄罗斯联邦法律。"},"12.2. Споры разрешаются путём переговоров; досудебная претензия направляется на электронную почту Правообладателя. Срок ответа на претензию — до 15 рабочих дней.":{"en":"12.2. Disputes are resolved through negotiation; a pre-trial claim is sent to the Rights Holder’s email. The response period for a claim is up to 15 business days.","fr":"12.2. Les litiges sont réglés par voie de négociation ; une réclamation préalable est adressée à l’e-mail du Titulaire des droits. Le délai de réponse est de 15 jours ouvrés maximum.","de":"12.2. Streitigkeiten werden durch Verhandlungen beigelegt; eine vorgerichtliche Beschwerde wird an die E-Mail des Rechteinhabers gesendet. Die Antwortfrist beträgt bis zu 15 Werktage.","es":"12.2. Las controversias se resuelven mediante negociación; la reclamación previa se envía al correo del Titular. El plazo de respuesta es de hasta 15 días hábiles.","it":"12.2. Le controversie si risolvono tramite trattativa; il reclamo stragiudiziale va inviato all’email del Titolare. Il termine di risposta è di 15 giorni lavorativi al massimo.","zh":"12.2. 争议通过协商解决；诉前索赔请发送至权利人的电子邮箱。答复期限最长 15 个工作日。"},"Дата вступления в силу: 22 октября 2026 г.":{"en":"Effective date: 22 October 2026","fr":"Date d’entrée en vigueur : 22 octobre 2026","de":"Gültig ab: 22. Oktober 2026","es":"Fecha de entrada en vigor: 22 de octubre de 2026","it":"Data di entrata in vigore: 22 ottobre 2026","zh":"生效日期：2026 年 10 月 22 日"},"— платный доступ к расширенным возможностям Сервиса на оплаченный срок (неделя или месяц) без автоматических списаний.":{"en":"— paid access to the Service’s extended features for a paid term (a week or a month) without automatic charges.","fr":"— accès payant aux fonctions étendues du Service pour une durée payée (une semaine ou un mois), sans prélèvement automatique.","de":"— kostenpflichtiger Zugang zu den erweiterten Funktionen des Dienstes für eine bezahlte Laufzeit (eine Woche oder einen Monat) ohne automatische Abbuchungen.","es":"— acceso de pago a las funciones ampliadas del Servicio por un periodo pagado (una semana o un mes), sin cobros automáticos.","it":"— accesso a pagamento alle funzioni estese del Servizio per un periodo pagato (una settimana o un mese), senza addebiti automatici.","zh":"——在已付期限（一周或一个月）内付费使用本服务扩展功能，不自动扣费。"},"3.2. В состав Pro-подписки входят: флагманская модель Dynatos, лимиты использования в 25 раз выше, чем в бесплатном тарифе, распознавание мелодий и нотная запись, генерация изображений моделью повышенного качества, возможность приглашать друзей в порядке п. 5.5.":{"en":"3.2. The Pro subscription includes: the flagship Dynatos model, usage limits 25 times higher than on the free plan, melody recognition and music notation, image generation with a higher-quality model, and the ability to invite friends under clause 5.5.","fr":"3.2. L’abonnement Pro comprend : le modèle phare Dynatos, des limites d’utilisation 25 fois plus élevées que le forfait gratuit, la reconnaissance de mélodies et la notation musicale, la génération d’images par un modèle de meilleure qualité et la possibilité d’inviter des amis selon le point 5.5.","de":"3.2. Das Pro-Abo umfasst: das Flaggschiffmodell Dynatos, Nutzungslimits, die 25-mal höher sind als im kostenlosen Tarif, Melodieerkennung und Notenschrift, Bildgenerierung mit einem hochwertigeren Modell sowie die Möglichkeit, Freunde gemäß Ziffer 5.5 einzuladen.","es":"3.2. La suscripción Pro incluye: el modelo insignia Dynatos, límites de uso 25 veces mayores que en el plan gratuito, reconocimiento de melodías y notación musical, generación de imágenes con un modelo de mayor calidad y la posibilidad de invitar a amigos según el punto 5.5.","it":"3.2. L’abbonamento Pro comprende: il modello di punta Dynatos, limiti di utilizzo 25 volte più alti rispetto al piano gratuito, riconoscimento delle melodie e notazione musicale, generazione di immagini con un modello di qualità superiore e la possibilità di invitare amici ai sensi del punto 5.5.","zh":"3.2. Pro 订阅包括：旗舰模型 Dynatos、比免费方案高 25 倍的使用额度、旋律识别与记谱、使用更高质量模型生成图片，以及按第 5.5 条邀请好友。"},"3.3. Подписка действует 30 дней (месячная) или 7 дней (недельная) с момента оплаты в зависимости от выбранного срока (далее — «Оплаченный период») и продлевается в порядке раздела 6 настоящей Оферты.":{"en":"3.3. The subscription is valid for 30 days (monthly) or 7 days (weekly) from the moment of payment, depending on the chosen term (the “Paid Period”), and is renewed in accordance with section 6 of this Offer.","fr":"3.3. L’abonnement est valable 30 jours (mensuel) ou 7 jours (hebdomadaire) à compter du paiement selon la durée choisie (la « Période payée ») et se prolonge conformément à la section 6 de la présente Offre.","de":"3.3. Das Abo gilt je nach gewählter Laufzeit 30 Tage (Monat) oder 7 Tage (Woche) ab der Zahlung (der „bezahlte Zeitraum“) und wird gemäß Abschnitt 6 dieses Angebots verlängert.","es":"3.3. La suscripción es válida durante 30 días (mensual) o 7 días (semanal) desde el pago, según el plazo elegido (el «Periodo pagado»), y se renueva conforme a la sección 6 de esta Oferta.","it":"3.3. L’abbonamento è valido 30 giorni (mensile) o 7 giorni (settimanale) dal pagamento, a seconda della durata scelta (il «Periodo pagato»), e si rinnova secondo la sezione 6 della presente Offerta.","zh":"3.3. 订阅自付款之日起按所选期限有效 30 天（按月）或 7 天（按周）（下称“已付期限”），并按本要约第 6 节续期。"},"4.1. Сообщения и генерации изображений в рамках Pro-подписки ограничены лимитами, которые в 25 раз выше лимитов бесплатного тарифа. Лимиты действуют в каждом 5-часовом окне, в течение недели и календарного месяца и обновляются автоматически.":{"en":"4.1. Messages and image generations under the Pro subscription are subject to limits that are 25 times higher than those of the free plan. The limits apply to every 5-hour window, to each week and to each calendar month and refresh automatically.","fr":"4.1. Les messages et générations d’images de l’abonnement Pro sont soumis à des limites 25 fois plus élevées que celles du forfait gratuit. Elles s’appliquent à chaque fenêtre de 5 heures, à chaque semaine et à chaque mois civil et se renouvellent automatiquement.","de":"4.1. Nachrichten und Bildgenerierungen im Pro-Abo unterliegen Limits, die 25-mal höher sind als im kostenlosen Tarif. Die Limits gelten für jedes 5-Stunden-Fenster, jede Woche und jeden Kalendermonat und erneuern sich automatisch.","es":"4.1. Los mensajes y generaciones de imágenes de la suscripción Pro están sujetos a límites 25 veces mayores que los del plan gratuito. Los límites se aplican a cada ventana de 5 horas, a cada semana y a cada mes natural y se renuevan automáticamente.","it":"4.1. I messaggi e le generazioni di immagini dell’abbonamento Pro sono soggetti a limiti 25 volte più alti di quelli del piano gratuito. I limiti valgono per ogni finestra di 5 ore, per ogni settimana e per ogni mese solare e si rinnovano automaticamente.","zh":"4.1. Pro 订阅中的消息和图片生成受额度限制，额度为免费方案的 25 倍。额度按每 5 小时窗口、每周和每个自然月计算，并自动刷新。"},"4.2. Кроме того, Сервис применяет автоматическую защиту от злоупотребления: при очень частых запросах подряд (например, более 25 сообщений в течение трёх минут) генерация может быть временно приостановлена на несколько минут.":{"en":"4.2. In addition, the Service applies automatic abuse protection: with very frequent back-to-back requests (for example, more than 25 messages within three minutes), generation may be paused for a few minutes.","fr":"4.2. En outre, le Service applique une protection automatique contre les abus : en cas de requêtes très rapprochées (par exemple plus de 25 messages en trois minutes), la génération peut être suspendue quelques minutes.","de":"4.2. Zusätzlich setzt der Dienst einen automatischen Missbrauchsschutz ein: Bei sehr vielen Anfragen direkt hintereinander (z. B. mehr als 25 Nachrichten innerhalb von drei Minuten) kann die Generierung für einige Minuten pausiert werden.","es":"4.2. Además, el Servicio aplica una protección automática contra abusos: ante solicitudes muy seguidas (por ejemplo, más de 25 mensajes en tres minutos), la generación puede pausarse unos minutos.","it":"4.2. Inoltre, il Servizio applica una protezione automatica contro gli abusi: in caso di richieste molto ravvicinate (ad esempio oltre 25 messaggi in tre minuti), la generazione può essere sospesa per alcuni minuti.","zh":"4.2. 此外，本服务启用自动防滥用保护：如连续请求过于频繁（例如三分钟内超过 25 条消息），生成可能暂停几分钟。"},"4.4. Для бесплатного тарифа действуют лимиты в каждом 5-часовом окне, в течение недели и календарного месяца. В разделе «Использование» отображается процент использованного объёма. После исчерпания лимита генерация приостанавливается до его обновления либо до оформления Pro-подписки. Если лимиты заканчиваются во время большой задачи, Сервис предупреждает об этом и предлагает продолжить после обновления лимита.":{"en":"4.4. The free plan has limits for every 5-hour window, each week and each calendar month. The “Usage” section shows the percentage used. Once a limit is reached, generation pauses until it refreshes or until a Pro subscription is purchased. If limits run out during a large task, the Service warns about it and offers to continue after the limit refreshes.","fr":"4.4. Le forfait gratuit comporte des limites pour chaque fenêtre de 5 heures, chaque semaine et chaque mois civil. La section « Utilisation » indique le pourcentage consommé. Une fois la limite atteinte, la génération est suspendue jusqu’à son renouvellement ou la souscription à Pro. Si les limites s’épuisent pendant une tâche importante, le Service vous en avertit et propose de continuer après le renouvellement.","de":"4.4. Im kostenlosen Tarif gelten Limits für jedes 5-Stunden-Fenster, jede Woche und jeden Kalendermonat. Im Bereich „Nutzung“ wird der verbrauchte Anteil in Prozent angezeigt. Ist ein Limit erreicht, pausiert die Generierung bis zur Erneuerung oder bis zum Abschluss eines Pro-Abos. Gehen die Limits während einer großen Aufgabe zur Neige, weist der Dienst darauf hin und bietet an, nach der Erneuerung fortzufahren.","es":"4.4. El plan gratuito tiene límites para cada ventana de 5 horas, cada semana y cada mes natural. La sección «Uso» muestra el porcentaje consumido. Al agotarse un límite, la generación se pausa hasta su renovación o hasta contratar Pro. Si los límites se agotan durante una tarea grande, el Servicio avisa y ofrece continuar tras la renovación.","it":"4.4. Il piano gratuito prevede limiti per ogni finestra di 5 ore, per ogni settimana e per ogni mese solare. La sezione «Utilizzo» mostra la percentuale consumata. Esaurito un limite, la generazione si sospende fino al rinnovo o all’attivazione di Pro. Se i limiti si esauriscono durante un compito impegnativo, il Servizio avvisa e propone di continuare dopo il rinnovo.","zh":"4.4. 免费方案按每 5 小时窗口、每周和每个自然月设有额度。“使用情况”中显示已用比例。额度用完后，生成会暂停，直到额度刷新或开通 Pro 订阅。如果大型任务进行中额度即将用完，本服务会提前提醒，并在额度刷新后提供继续选项。"},"5.1. Стоимость Pro-подписки — 299 (двести девяносто девять) рублей за 30 дней или 129 (сто двадцать девять) рублей за 7 дней. Правообладатель вправе изменять стоимость для новых оплаченных периодов; стоимость уже оплаченного периода не меняется.":{"en":"5.1. The Pro subscription costs 299 (two hundred ninety-nine) rubles for 30 days or 129 (one hundred twenty-nine) rubles for 7 days. The Rights Holder may change the price for new paid periods; the price of an already paid period does not change.","fr":"5.1. L’abonnement Pro coûte 299 (deux cent quatre-vingt-dix-neuf) roubles pour 30 jours ou 129 (cent vingt-neuf) roubles pour 7 jours. Le Titulaire des droits peut modifier le prix des nouvelles périodes payées ; le prix d’une période déjà payée ne change pas.","de":"5.1. Das Pro-Abo kostet 299 (zweihundertneunundneunzig) Rubel für 30 Tage oder 129 (einhundertneunundzwanzig) Rubel für 7 Tage. Der Rechteinhaber darf den Preis für neue bezahlte Zeiträume ändern; der Preis eines bereits bezahlten Zeitraums ändert sich nicht.","es":"5.1. La suscripción Pro cuesta 299 (doscientos noventa y nueve) rublos por 30 días o 129 (ciento veintinueve) rublos por 7 días. El Titular de los derechos puede cambiar el precio de los nuevos periodos pagados; el precio de un periodo ya pagado no cambia.","it":"5.1. L’abbonamento Pro costa 299 (duecentonovantanove) rubli per 30 giorni o 129 (centoventinove) rubli per 7 giorni. Il Titolare dei diritti può modificare il prezzo per i nuovi periodi pagati; il prezzo di un periodo già pagato non cambia.","zh":"5.1. Pro 订阅价格为 30 天 299（贰佰玖拾玖）卢布或 7 天 129（壹佰贰拾玖）卢布。权利人有权调整新付费期限的价格；已付期限的价格不变。"},"5.5. Реферальная программа. Пользователь, хотя бы один раз оплативший Pro-подписку, вправе отправить не более двух приглашений. Приглашённый, у аккаунта которого ранее не было Pro-подписки, однократно получает Pro-подписку на 3 дня и скидку 10% на первую оплату месячной подписки. На недельную подписку скидка не распространяется. Приглашение может быть использовано один раз; Правообладатель вправе отменить преимущества, полученные с нарушением настоящего пункта.":{"en":"5.5. Referral program. A User who has paid for the Pro subscription at least once may send no more than two invitations. An invitee whose account has never had a Pro subscription receives, once, a 3-day Pro subscription and a 10% discount on the first payment for a monthly subscription. The discount does not apply to the weekly subscription. Each invitation can be used once; the Rights Holder may revoke benefits obtained in violation of this clause.","fr":"5.5. Programme de parrainage. Un Utilisateur ayant payé l’abonnement Pro au moins une fois peut envoyer au plus deux invitations. L’invité dont le compte n’a jamais eu d’abonnement Pro reçoit, une seule fois, 3 jours d’abonnement Pro et une remise de 10 % sur le premier paiement d’un abonnement mensuel. La remise ne s’applique pas à l’abonnement hebdomadaire. Chaque invitation n’est utilisable qu’une fois ; le Titulaire des droits peut annuler les avantages obtenus en violation du présent point.","de":"5.5. Empfehlungsprogramm. Ein Nutzer, der das Pro-Abo mindestens einmal bezahlt hat, darf höchstens zwei Einladungen versenden. Ein Eingeladener, dessen Konto noch nie ein Pro-Abo hatte, erhält einmalig 3 Tage Pro und 10 % Rabatt auf die erste Zahlung eines Monats-Abos. Für das Wochen-Abo gilt der Rabatt nicht. Jede Einladung kann einmal verwendet werden; der Rechteinhaber darf Vorteile widerrufen, die unter Verstoß gegen diese Ziffer erlangt wurden.","es":"5.5. Programa de referidos. Un Usuario que haya pagado la suscripción Pro al menos una vez puede enviar como máximo dos invitaciones. El invitado cuya cuenta nunca haya tenido suscripción Pro recibe, una sola vez, 3 días de suscripción Pro y un 10 % de descuento en el primer pago de una suscripción mensual. El descuento no se aplica a la suscripción semanal. Cada invitación puede usarse una vez; el Titular de los derechos puede anular los beneficios obtenidos en infracción de este punto.","it":"5.5. Programma di inviti. Un Utente che ha pagato l’abbonamento Pro almeno una volta può inviare al massimo due inviti. L’invitato il cui account non ha mai avuto un abbonamento Pro riceve, una sola volta, 3 giorni di abbonamento Pro e uno sconto del 10% sul primo pagamento di un abbonamento mensile. Lo sconto non si applica all’abbonamento settimanale. Ogni invito può essere usato una sola volta; il Titolare dei diritti può revocare i vantaggi ottenuti in violazione del presente punto.","zh":"5.5. 推荐计划。至少付费订阅过一次 Pro 的用户最多可发送两份邀请。从未开通过 Pro 订阅的受邀用户可一次性获得 3 天 Pro 订阅，以及首次按月订阅付款 9 折优惠。按周订阅不享受折扣。每份邀请仅可使用一次；对违反本条获得的权益，权利人有权撤销。"},"6. Продление, отмена и изменение стоимости":{"en":"6. Renewal, cancellation and price changes","fr":"6. Prolongation, résiliation et modification du prix","de":"6. Verlängerung, Kündigung und Preisänderung","es":"6. Renovación, cancelación y cambio de precio","it":"6. Rinnovo, annullamento e variazione del prezzo","zh":"6. 续期、取消与价格变更"},"6.1. Автоматических списаний нет: подписка продлевается только при оплате Пользователем очередного периода (раздел «Подписка» в настройках Сервиса или страница оформления подписки). Если оплата произведена до окончания текущего Оплаченного периода, новый период прибавляется к оставшемуся сроку.":{"en":"6.1. There are no automatic charges: the subscription is renewed only when the User pays for the next period (the “Subscription” section in the Service settings or the subscription page). If payment is made before the current Paid Period ends, the new period is added to the remaining term.","fr":"6.1. Aucun prélèvement automatique : l’abonnement n’est prolongé que lorsque l’Utilisateur paie la période suivante (section « Abonnement » des paramètres du Service ou page d’abonnement). Si le paiement intervient avant la fin de la Période payée en cours, la nouvelle période s’ajoute à la durée restante.","de":"6.1. Es gibt keine automatischen Abbuchungen: Das Abo verlängert sich nur, wenn der Nutzer den nächsten Zeitraum bezahlt (Bereich „Abo“ in den Einstellungen des Dienstes oder die Abo-Seite). Erfolgt die Zahlung vor Ende des laufenden bezahlten Zeitraums, wird der neue Zeitraum zur Restlaufzeit addiert.","es":"6.1. No hay cobros automáticos: la suscripción solo se renueva cuando el Usuario paga el siguiente periodo (sección «Suscripción» en los ajustes del Servicio o la página de suscripción). Si el pago se realiza antes de que termine el Periodo pagado actual, el nuevo periodo se suma al plazo restante.","it":"6.1. Nessun addebito automatico: l’abbonamento si rinnova solo quando l’Utente paga il periodo successivo (sezione «Abbonamento» nelle impostazioni del Servizio o pagina di abbonamento). Se il pagamento avviene prima della fine del Periodo pagato in corso, il nuovo periodo si somma al tempo residuo.","zh":"6.1. 不自动扣费：只有用户支付下一期费用时订阅才会续期（在本服务设置的“订阅”部分或订阅页面）。如在当前已付期限结束前付款，新期限将累加到剩余期限上。"},"6.2. Отмена подписки осуществляется через поддержку Сервиса (Telegram":{"en":"6.2. The subscription is cancelled through the Service’s support (Telegram","fr":"6.2. La résiliation de l’abonnement s’effectue via le support du Service (Telegram","de":"6.2. Die Kündigung des Abos erfolgt über den Support des Dienstes (Telegram","es":"6.2. La cancelación de la suscripción se realiza a través del soporte del Servicio (Telegram","it":"6.2. L’annullamento dell’abbonamento avviene tramite il supporto del Servizio (Telegram","zh":"6.2. 取消订阅须通过本服务客服办理（Telegram"},"или почта":{"en":"or email","fr":"ou e-mail","de":"oder E-Mail","es":"o correo","it":"o e-mail","zh":"或邮箱"},"). При отмене доступ к Pro-функциям сохраняется до конца уже оплаченного периода, если иное не согласовано при рассмотрении обращения в порядке раздела 7.":{"en":"). Upon cancellation, access to Pro features remains until the end of the already paid period, unless otherwise agreed when the request is reviewed under section 7.","fr":"). En cas de résiliation, l’accès aux fonctions Pro est conservé jusqu’à la fin de la période déjà payée, sauf accord contraire lors de l’examen de la demande selon la section 7.","de":"). Nach der Kündigung bleibt der Zugang zu den Pro-Funktionen bis zum Ende des bereits bezahlten Zeitraums bestehen, sofern bei der Prüfung des Anliegens gemäß Abschnitt 7 nichts anderes vereinbart wird.","es":"). Tras la cancelación, el acceso a las funciones Pro se mantiene hasta el final del periodo ya pagado, salvo que se acuerde otra cosa al revisar la solicitud según la sección 7.","it":"). In caso di annullamento, l’accesso alle funzioni Pro resta attivo fino alla fine del periodo già pagato, salvo diverso accordo in sede di esame della richiesta ai sensi della sezione 7.","zh":"）。取消后，Pro 功能可使用至已付期限结束，除非按第 7 节处理申请时另有约定。"},"6.3. Изменение стоимости применяется только к периодам, оплаченным после такого изменения. Актуальная стоимость указывается на странице оформления подписки до оплаты.":{"en":"6.3. A price change applies only to periods paid after the change. The current price is shown on the subscription page before payment.","fr":"6.3. Une modification de prix ne s’applique qu’aux périodes payées après celle-ci. Le prix en vigueur est indiqué sur la page d’abonnement avant le paiement.","de":"6.3. Eine Preisänderung gilt nur für Zeiträume, die nach der Änderung bezahlt werden. Der aktuelle Preis wird vor der Zahlung auf der Abo-Seite angezeigt.","es":"6.3. Un cambio de precio solo se aplica a los periodos pagados después de dicho cambio. El precio vigente se muestra en la página de suscripción antes del pago.","it":"6.3. La variazione del prezzo si applica solo ai periodi pagati dopo la variazione. Il prezzo attuale è indicato nella pagina di abbonamento prima del pagamento.","zh":"6.3. 价格变更仅适用于变更后支付的期限。现行价格会在付款前显示在订阅页面上。"}});
